input.new_string:
if balance_cents < 0 or days_late < 0:
    raise ValueError("balance_cents and days_late must be non-negative")
if balance_cents == 0 or days_late <= GRACE_DAYS:
    return 0
# Ceiling division: days 1-30 are period 1, 31-60 are period 2, etc.
periods = (days_late + PERIOD_DAYS - 1) // PERIOD_DAYS
# Calculate fee with rounding half up
fee = (balance_cents * RATE_BP * periods + 5000) // 10000
if fee < MINIMUM_FEE_CENTS:
    # When minimum applies, cap is reduced by the fee rate
    cap_bp = 2000 - RATE_BP * periods  # 2000 bp = 20% = 1/5
    cap = balance_cents * cap_bp // 10000
    fee = MINIMUM_FEE_CENTS
else:
    cap = balance_cents // 5
return min(fee, cap)
